-- Actual seller/webhook contracts; financial identities remain authoritative in financial_transactions.
CREATE TABLE seller_settings(channel TEXT PRIMARY KEY, data JSONB NOT NULL DEFAULT '{}');
CREATE TABLE seller_mappings(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), channel TEXT NOT NULL, product_id UUID NOT NULL REFERENCES products(id), buyer_sku_code TEXT NOT NULL, enabled BOOLEAN NOT NULL DEFAULT true, data JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(channel,buyer_sku_code), UNIQUE(channel,product_id));
CREATE TABLE seller_orders(id UUID PRIMARY KEY DEFAULT gen_random_uuid(), channel TEXT NOT NULL, reference_id TEXT NOT NULL, product_id UUID REFERENCES products(id), buyer_sku_code TEXT NOT NULL DEFAULT '', customer_no TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','processing','success','failed')), amount BIGINT NOT NULL DEFAULT 0 CHECK(amount>=0), snapshot JSONB NOT NULL DEFAULT '{}', response JSONB NOT NULL DEFAULT '{}', callback_url TEXT NOT NULL DEFAULT '', vendor_reference TEXT UNIQUE, execution_token UUID, execution_lease_until TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(channel,reference_id));
CREATE TABLE seller_event_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),channel TEXT NOT NULL,reference_id TEXT NOT NULL DEFAULT '',event TEXT NOT NULL,status TEXT NOT NULL,message TEXT NOT NULL,verified BOOLEAN NOT NULL DEFAULT false,request_ip TEXT NOT NULL DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX seller_event_logs_recent ON seller_event_logs(channel,created_at DESC);
CREATE INDEX seller_orders_recent ON seller_orders(channel,created_at DESC);
CREATE TABLE webhook_settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE webhook_event_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),provider TEXT NOT NULL,event TEXT NOT NULL,reference_id TEXT NOT NULL,status TEXT NOT NULL,message TEXT NOT NULL,verified BOOLEAN NOT NULL,request_ip TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX webhook_event_logs_recent ON webhook_event_logs(provider,created_at DESC);
ALTER TABLE seller_callbacks ADD COLUMN order_id UUID REFERENCES seller_orders(id), ADD COLUMN payload JSONB NOT NULL DEFAULT '{}', ADD COLUMN callback_url TEXT NOT NULL DEFAULT '', ADD COLUMN lease_token UUID, ADD COLUMN lease_until TIMESTAMPTZ, ADD COLUMN generation BIGINT NOT NULL DEFAULT 1, ADD COLUMN last_status_code INTEGER, ADD COLUMN last_attempt_at TIMESTAMPTZ;
CREATE INDEX seller_callbacks_due ON seller_callbacks(next_retry_at) WHERE delivered_at IS NULL;
